cd /tmp && python3 -c "
import openpyxl
wb = openpyxl.load_workbook('$PWD/budget.xlsx', data_only=True)
for name in wb.sheetnames:
    print('Sheet:', name)
    ws = wb[name]
    print('dims:', ws.dimensions)
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None:
                print(c.coordinate, repr(c.value))
    print('---')
